[TFMListIdAttribute('OrderLines')]
public class TFMListOrderLines extends TFMList
{
    boolean dontShowDimTracking;
    boolean dontShowDimProduct;
    boolean dontShowDimStorage;
}

Method.Source:
    public TFMListConfiguration getList()
    {
        TFMListConfiguration					listConfig	= TFMListConfiguration::Construct(listName);
        TFMListRow								row			= listConfig.addRow();
        TFMListColumn							column		= row.makeColumn(65);
        TFMListCustomComponentDimensionDisplay	dimDisplay  = new TFMListCustomComponentDimensionDisplay();
		listConfig.parmDisplayStatus(true);
        column.addElement(TFMListTextElement::ConstructTextElement('{'+extendedTypeStr(ItemName)+'}',TFMFonts::FindOrCreateFromProperties('contentFontBold',TFMFontSizes::medium,true,false,'').id));
        row.makeColumn(35).addElement(TFMListTextElement::ConstructTextElement(this.quantityCellContent(),TFMFonts::FindOrCreateFromProperties('MediumContentFont',TFMFontSizes::medium,false,false,'').id,SysChartHorizontalAlignment::Right));

        row			= listConfig.addRow();
        TFMListColumns columns = TFMListColumns::Construct();
        row.addChild(columns);
        dimDisplay.parmItemID(true);
		dimDisplay.parmProductDimensions(!dontShowDimProduct);
        dimDisplay.parmStorageDimensions(!dontShowDimStorage);
        dimDisplay.parmTrackingDimensions(!dontShowDimTracking);
		dimDisplay.parmwidth(80);
        columns.addChild(dimDisplay);

        column = row.makeColumn(20);
		column.addElement(TFMListImageElement::ConstructImageElement('{imageId}','',20,0));
        column.addElement(TFMListImageElement::ConstructImageElement('{attachmentImage}','',5,0,SysChartHorizontalAlignment::Right,TFMVerticalAlignment::Bottom));

        return listConfig;
    }
